raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R07-01",
   "status": "OK",
   "label": "저금통 설정 금리 우대",
   "source": {
    "quote": "▪ 연 1.9% (최대 100만원까지)"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "product.type"
       },
       ["LOW_SAVINGS_TANK"]
      ]
     },
     {
      "<=": [
       {
        "var": "account.reserved_amount"
       },
       1000000
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 1.9,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R07-02",
   "status": "OK",
   "label": "저금통 설정 한도",
   "source": {
    "quote": "적용한도 : 저금통 금액 설정은 최대 100만원(1만원 단위)까지 가능"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "product.type"
       },
       ["LOW_SAVINGS_TANK"]
      ]
     },
     {
      "not": {
        "in": [
         {
          "var": "account.reserved_amount"
         },
         [1000000]
        ]
       }
      }
     }
    ]
   },
   "effect": {
    "type": "LIMIT_AMOUNT",
    "value": 1000000
   }
  }
 ]
}

